## ---- 01: The `setModel` Interface  (qmd line 29) ------------------------------------

library(yuima)

# The two model-specific arguments, built in full later in this chapter
drift_expressions <- c("0.08*(0.04 - beta1)",
                       "0.40*(-0.01 - beta2)",
                       "0.60*(0.01 - beta3)")
diffusion_matrix  <- diag(c(0.005, 0.012, 0.020))

yuima_model <- yuima::setModel(
  drift          = drift_expressions,   # character vector of drift terms
  diffusion      = diffusion_matrix,    # matrix of diffusion coefficients
  state.variable = c("beta1", "beta2", "beta3"),
  solve.variable = c("beta1", "beta2", "beta3"),
  jump.coeff     = NULL,                 # for Lévy-driven extensions
  measure        = list(),               # for Lévy-driven extensions
  measure.type   = character(),
  xinit          = c(0.04, -0.01, 0.01)  # initial state
)


## ---- 02: The `setSampling` Interface  (qmd line 63) ---------------------------------

sampling <- yuima::setSampling(
  Initial   = 0,
  Terminal  = 30,       # 30-year horizon
  n         = 360,      # 360 monthly steps
  delta     = 1/12,     # time step in years
  grid      = NULL,     # optional custom grid
  random    = FALSE,    # regular (non-random) sampling
  sdelta    = NULL,
  sgrid     = NULL,
  interpolation = "pt"
)


## ---- 03: The `simulate` Method  (qmd line 83) ---------------------------------------

initial_factors  <- c(0.045, -0.005, 0.012)  # level, slope, curvature
true_params_list <- list()                   # drift/diffusion are numeric

yuima_sim <- yuima::simulate(
  yuima_model,
  sampling     = sampling,
  xinit        = initial_factors,
  true.parameter = true_params_list,
  space.discretized = FALSE,
  increment.L    = NULL,
  increment.W    = NULL,
  method         = "euler"    # or "Thinning" for jump-driven models
)


## ---- 04: Model Specification for DNS  (qmd line 105) ---------------------------------

# Conceptual construction
kappa  <- c(0.08, 0.40, 0.60)  # level, slope, curvature speeds
theta  <- c(0.04, -0.01, 0.01) # long-run means
sigma  <- c(0.005, 0.012, 0.020)  # volatilities
corr   <- matrix(c(1, -0.35, 0.20,
                   -0.35, 1, -0.40,
                   0.20, -0.40, 1), 3, 3)

# Drift string: e.g., "0.08*0.04 - 0.08*beta1"
drift <- sprintf("%f*%f - %f*%s",
                 kappa, theta, kappa, c("beta1","beta2","beta3"))

# Diffusion = diag(sigma) %*% Cholesky(corr)
Sigma <- diag(sigma) %*% corr %*% diag(sigma)
diffusion <- t(chol(Sigma))

yuima_model <- yuima::setModel(
  drift          = drift,
  diffusion      = diffusion,
  state.variable = c("beta1", "beta2", "beta3"),
  solve.variable = c("beta1", "beta2", "beta3")
)


## ---- 05: DNS Calibration Workflow  (qmd line 136) ------------------------------------

library(dnsr)

# Step 1: Download Treasury yields from FRED
yield_data <- get_treasury_yield_combined(start_date = "2020-01-01")

# Step 2: Fit DNS cross-sectionally to each day's curve over a
# multi-year window, holding lambda fixed across dates so the factor
# series below is measured against one set of loadings. The panel's
# maturities are in years, so lambda is per year (Chapter 2).
dns_result <- fit_dns_model(yield_data, n_days = 1250,
                            lambda_constraint = "fixed",
                            initial_lambda = 0.7308)

# Step 3: Estimate OU dynamics from the month-end factor series
pars    <- dns_result$parameters[order(dns_result$parameters$Date), ]
monthly <- pars[!duplicated(format(pars$Date, "%Y-%m"), fromLast = TRUE), ]
for (f in c("beta1", "beta2", "beta3")) {
  monthly[[paste0(f, "_change")]] <- c(NA, diff(monthly[[f]]))
}
dynamics <- estimate_dns_dynamics(monthly, dt = 1/12)

# Step 4: Simulate yield curve paths via YUIMA
sim <- simulate_dns_yield_curves(
  params          = dns_dynamics_to_sim_params(dynamics),
  initial_factors = unlist(dns_result$parameters[1, c("beta1","beta2","beta3")]),
  maturities      = c(0.25, 0.5, 1, 2, 3, 5, 7, 10, 20, 30),
  time_horizon    = 30,
  n_steps         = 360,
  n_paths         = 500,
  sim_method      = "euler"
)


