## ---- 07: A Worked End-to-End Example  (qmd line 303) ---------------------------------

library(dnsr)
library(yuima)

# 1. Calibrate parameters over a multi-year window (or use defaults),
#    with the decay rate held fixed across dates
calib <- get_calibrated_dns_params(lookback_days = 1250,
                                    lambda = ns_lambda(3.5))

# 2. Build the YUIMA model
yuima_mod <- dns_to_yuima_model(calib$params)

# 3. Set sampling
sampling <- setSampling(Initial = 0, Terminal = 30, n = 360)

# 4. Simulate
sim_result <- simulate(yuima_mod, sampling = sampling)

# 5. Extract factors and compute yields
maturities   <- c(0.25, 0.5, 1, 2, 3, 5, 7, 10, 20, 30)
factors_path <- do.call(cbind, lapply(get.zoo.data(sim_result), as.numeric))
yields_path  <- calculate_dns_yields(factors_path, maturities,
                                     lambda = calib$lambda)

# 6. Check diagnostics: fan chart and stationary moments across paths
factor_sim <- simulate_dns_factors(calib$params, calib$initial_factors,
                                   time_horizon = 30, n_steps = 360,
                                   n_paths = 500)
plot_simulated_factors(factor_sim)
colMeans(factor_sim$factors[361, , ])   # long-run means vs calib$params$theta


## ---- 08: Building a YUIMA Model from DNS Parameters  (qmd line 354) ------------------

library(yuima)
library(dnsr)

kappa <- c(0.08, 0.40, 0.60)
theta <- c(0.04, -0.01, 0.01)
sigma <- c(0.005, 0.012, 0.020)
R <- matrix(c(1, -0.35, 0.20,
              -0.35, 1, -0.40,
              0.20, -0.40, 1), 3, 3)
Sigma <- diag(sigma) %*% R %*% diag(sigma)
diff_mat <- t(chol(Sigma))

drift <- sprintf("%f - %f * %s", kappa * theta, kappa,
                 c("beta1","beta2","beta3"))

mod <- setModel(drift = drift,
                diffusion = diff_mat,
                state.variable = c("beta1","beta2","beta3"),
                solve.variable = c("beta1","beta2","beta3"),
                xinit = c(0.04, -0.01, 0.01))


## ---- 09: Simulation  (qmd line 379) --------------------------------------------------

samp <- setSampling(Initial = 0, Terminal = 30, n = 360)
sim  <- simulate(mod, sampling = samp,
                 true.parameter = list())

zoo_data <- do.call(merge, get.zoo.data(sim))

library(ggplot2)
factors_df <- zoo::fortify.zoo(zoo_data, melt = TRUE)
levels(factors_df$Series) <- c("L", "S", "C")
ggplot(factors_df, aes(Index, Value, colour = Series)) +
  geom_line() +
  labs(x = "Time (years)", y = "Factor value", colour = NULL) +
  theme_minimal()


